  };

  const saveSite = async () => {
    if (!form.name.trim() || !map) { setError('Choose a map and enter a dive site name.'); return; }
    const latitude = Number(form.latitude); const longitude = Number(form.longitude);
    if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) { setError('Enter valid coordinates for the pin.'); return; }
    setSaving(true); setError('');
    const routes = form.routeName.trim() ? [{ name: form.routeName.trim(), notes: form.routeNotes.trim() || undefined, points: parsePoints(form.routePoints) }] : [];
    const payload = { mapKey: map.key, name: form.name.trim(), description: form.description.trim() || undefined, latitude, longitude, minDepth: form.minDepth ? Number(form.minDepth) : undefined, maxDepth: form.maxDepth ? Number(form.maxDepth) : undefined, difficulty: form.difficulty.trim() || undefined, currentInfo: form.currentInfo.trim() || undefined, highlights: parseList(form.highlights), typicalSightings: normalizeSightings(selectedTypicalSightings), routes };
    try {
      const response = editing ? await API.patch(`/center/dive-sites/${editing.id}`, payload) : await API.post('/center/dive-sites', payload);
      const next = response.data as DiveSite;
      setSites((current) => editing ? current.map((site) => site.id === next.id ? next : site) : [...current, next].sort((a, b) => a.name.localeCompare(b.name)));
      setSelected(next); setModal(false);
    } catch (requestError: any) { const message = requestError?.response?.data?.message; setError(Array.isArray(message) ? message.join(' ') : message || 'Could not save this dive site.'); }
    finally { setSaving(false); }
  };

  const removeSite = async (site: DiveSite) => {
    setSaving(true); setError('');
    try { await API.delete(`/center/dive-sites/${site.id}`); setSites((current) => current.filter((candidate) => candidate.id !== site.id)); setSelected(null); }
    catch (requestError: any) { setError(requestError?.response?.data?.message || 'Could not remove this dive site.'); }
    finally { setSaving(false); }
  };

  const handleMapPress = (event: any, metrics?: { viewBoxX: number; viewBoxY: number; viewBoxWidth: number; viewBoxHeight: number; renderedWidth: number; renderedHeight: number }) => {
    if (!placing || !map) return;
    // React Native provides locationX/locationY, while react-native-svg on web
    // forwards a regular MouseEvent. Normalize both into the SVG viewBox.
    const nativeEvent = event?.nativeEvent || event;
    let x = Number(nativeEvent?.locationX ?? nativeEvent?.offsetX);
    let y = Number(nativeEvent?.locationY ?? nativeEvent?.offsetY);
    let renderedWidth = metrics?.renderedWidth || MAP_WIDTH;
    let renderedHeight = metrics?.renderedHeight || MAP_HEIGHT;
    if ((!Number.isFinite(x) || !Number.isFinite(y)) && Number.isFinite(nativeEvent?.clientX) && Number.isFinite(nativeEvent?.clientY)) {
      const svg = event?.currentTarget || event?.target;
      const rect = svg?.getBoundingClientRect?.();
      if (rect?.width && rect?.height) {
        x = nativeEvent.clientX - rect.left;
        y = nativeEvent.clientY - rect.top;
        renderedWidth = rect.width;
        renderedHeight = rect.height;
      }
    }
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;
    const viewBox = metrics || { viewBoxX: 0, viewBoxY: 0, viewBoxWidth: MAP_WIDTH, viewBoxHeight: MAP_HEIGHT, renderedWidth: MAP_WIDTH, renderedHeight: MAP_HEIGHT };
    x = (x / Math.max(1, renderedWidth)) * viewBox.viewBoxWidth + viewBox.viewBoxX;
    y = (y / Math.max(1, renderedHeight)) * viewBox.viewBoxHeight + viewBox.viewBoxY;
    x = Math.max(0, Math.min(MAP_WIDTH, x));
    y = Math.max(0, Math.min(MAP_HEIGHT, y));
    const latitude = map.bounds.north - (y / MAP_HEIGHT) * (map.bounds.north - map.bounds.south);
    const longitude = map.bounds.west + (x / MAP_WIDTH) * (map.bounds.east - map.bounds.west);
    openCreate({ latitude, longitude });
  };

  if (loading) return <View style={styles.center}><ActivityIndicator color="#123b52" /><Text style={styles.muted}>Loading operation mapâ€¦</Text></View>;

  return <ScrollView style={styles.screen} contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
    <View style={styles.hero}><View style={styles.heroCopy}><Text style={styles.eyebrow}>CENTER OPERATIONS</Text><Text style={styles.title}>Dive sites map</Text><Text style={styles.subtitle}>Build a local guide for your center and share the best routes with divers.</Text></View><View style={styles.heroBadge}><Text style={styles.heroValue}>{sites.length}</Text><Text style={styles.heroLabel}>sites mapped</Text></View></View>
    {error ? <Text accessibilityRole="alert" style={styles.error}>{error}</Text> : null}
    <View style={styles.mapChoice}><View style={styles.sectionCopy}><Text style={styles.sectionTitle}>Operation area</Text><Text style={styles.sectionHint}>Choose the coastal map where your center operates. More regions can be added later.</Text></View><View style={styles.mapOptions}>{catalog.map((candidate) => <TouchableOpacity key={candidate.key} disabled={saving} accessibilityRole="button" accessibilityState={{ selected: selectedMapKey === candidate.key }} onPress={() => chooseMap(candidate.key)} style={[styles.mapOption, selectedMapKey === candidate.key && styles.mapOptionActive]}><Text style={styles.mapOptionTitle}>{candidate.name}</Text><Text style={styles.mapOptionMeta}>{candidate.country}</Text></TouchableOpacity>)}</View></View>
    {map ? <>
      <View style={styles.toolbar}><View style={styles.searchBox}><TextInput accessibilityLabel="Search dive sites" placeholder="Search dive sites, wildlife or difficulty" value={query} onChangeText={setQuery} style={styles.searchInput} /></View><TouchableOpacity accessibilityRole="button" style={[styles.placeButton, placing && styles.placeButtonActive]} onPress={() => setPlacing((current) => !current)}><Text style={styles.placeButtonText}>{placing ? 'Click map to placeâ€¦' : '+ Place pin'}</Text></TouchableOpacity><TouchableOpacity accessibilityRole="button" style={styles.addButton} onPress={() => openCreate()}><Text style={styles.addButtonText}>Add details</Text></TouchableOpacity></View>
      <View style={styles.mapPanel}><View style={styles.mapPanelHeader}><View><Text style={styles.sectionTitle}>{map.name}</Text><Text style={styles.sectionHint}>{placing ? 'Click anywhere inside the map to set a new pin.' : 'Select a pin to open its dive site profile.'}</Text></View><Text style={styles.attribution}>{map.attribution}</Text></View><View style={styles.mapFrame}><PanglaoMap map={map} sites={visibleSites} selectedId={selected?.id} placing={placing} onSelect={(site) => { setSelected(site); setPlacing(false); }} onMapPress={handleMapPress} /></View></View>
      <View pointerEvents="none" style={styles.mapNotice}><Text style={styles.mapNoticeText}>Route preview</Text></View>
      {narrowLayout ? <View pointerEvents="none" style={styles.mapInfoStrip}><Text style={styles.mapInfoStripText}>Bohol Sea Â· drag to explore</Text></View> : null}
      <View style={styles.resultsHeader}><Text style={styles.sectionTitle}>Dive zones</Text><Text style={styles.sectionHint}>{visibleSites.length} shown</Text></View>
      <View pointerEvents="none" style={styles.zoneSummary}><Text style={styles.zoneSummaryText}>Showing all zones</Text></View>
      <View pointerEvents="none" style={styles.cardShadeA} />
      <View pointerEvents="none" style={styles.cardShadeB} />
      {narrowLayout ? <View pointerEvents="none" style={styles.narrowCardShade} /> : null}
      <View style={styles.siteGrid}>{visibleSites.map((site) => <TouchableOpacity key={site.id} accessibilityRole="button" accessibilityState={{ selected: selected?.id === site.id }} style={[styles.siteCard, selected?.id === site.id && styles.siteCardActive]} onPress={() => setSelected(site)}><View style={styles.siteCardTop}><Text style={styles.siteName}>{site.name}</Text><Text style={styles.difficulty}>{site.difficulty || 'Unrated'}</Text></View><Text numberOfLines={2} style={styles.siteDescription}>{site.description || 'No description yet.'}</Text><Text style={styles.siteMeta}>{site.minDepth ?? '?'}â€“{site.maxDepth ?? '?'} m Â· {(site.typicalSightings || []).length} typical sightings Â· {(site.routes || []).length} route{(site.routes || []).length === 1 ? '' : 's'}</Text></TouchableOpacity>)}</View>
      {!visibleSites.length ? <View style={styles.empty}><Text style={styles.emptyTitle}>No dive zones match</Text><Text style={styles.muted}>Try another search or place your first pin.</Text></View> : null}
      {selected ? <View style={styles.detailPanel}><View style={styles.detailCopy}><Text style={styles.eyebrow}>SELECTED DIVE ZONE</Text><Text style={styles.detailTitle}>{selected.name}</Text><Text style={styles.detailDescription}>{selected.description || 'Add a description so visiting divers know what to expect.'}</Text><Text style={styles.detailMeta}>{selected.latitude.toFixed(5)}, {selected.longitude.toFixed(5)} Â· {selected.difficulty || 'Difficulty not set'}</Text></View><View style={styles.detailActions}><TouchableOpacity accessibilityRole="button" onPress={() => navigation.navigate('CenterDiveSiteDetail', { siteId: selected.id })} style={styles.detailButton}><Text style={styles.detailButtonText}>Open site profile</Text></TouchableOpacity><TouchableOpacity accessibilityRole="button" onPress={() => openEdit(selected)} style={styles.editButton}><Text style={styles.editButtonText}>Edit</Text></TouchableOpacity><TouchableOpacity accessibilityRole="button" disabled={saving} onPress={() => removeSite(selected)} style={styles.deleteButton}><Text style={styles.deleteButtonText}>Remove</Text></TouchableOpacity></View></View> : null}
    </> : <View style={styles.empty}><Text style={styles.emptyTitle}>Choose your operation map</Text><Text style={styles.muted}>Select Panglao to start placing dive zones.</Text></View>}
    <Modal visible={modal} transparent animationType="slide" onRequestClose={() => setModal(false)}><View style={styles.backdrop}><View style={styles.modal}><ScrollView keyboardShouldPersistTaps="handled"><View style={styles.modalHeader}><View><Text style={styles.modalTitle}>{editing ? 'Edit dive site' : 'Add dive site'}</Text><Text style={styles.modalHint}>The pin stays inside the selected operation map.</Text></View><TouchableOpacity accessibilityLabel="Close dive site form" onPress={() => setModal(false)}><Text style={styles.close}>Ã—</Text></TouchableOpacity></View><Text style={styles.label}>Name *</Text><TextInput accessibilityLabel="Dive site name" value={form.name} onChangeText={(value) => setField('name', value)} placeholder="Balicasag Cathedral" style={styles.input} /><Text style={styles.label}>Description</Text><TextInput accessibilityLabel="Dive site description" multiline value={form.description} onChangeText={(value) => setField('description', value)} style={[styles.input, styles.multiline]} placeholder="What makes this zone special?" /><View style={styles.row}><View style={styles.half}><Text style={styles.label}>Latitude</Text><TextInput accessibilityLabel="Dive site latitude" keyboardType="decimal-pad" value={form.latitude} onChangeText={(value) => setField('latitude', value)} style={styles.input} /></View><View style={styles.half}><Text style={styles.label}>Longitude</Text><TextInput accessibilityLabel="Dive site longitude" keyboardType="decimal-pad" value={form.longitude} onChangeText={(value) => setField('longitude', value)} style={styles.input} /></View></View><View style={styles.row}><View style={styles.half}><Text style={styles.label}>Min depth (m)</Text><TextInput accessibilityLabel="Minimum depth" keyboardType="number-pad" value={form.minDepth} onChangeText={(value) => setField('minDepth', value)} style={styles.input} /></View><View style={styles.half}><Text style={styles.label}>Max depth (m)</Text><TextInput accessibilityLabel="Maximum depth" keyboardType="number-pad" value={form.maxDepth} onChangeText={(value) => setField('maxDepth', value)} style={styles.input} /></View></View><Text style={styles.label}>Difficulty</Text><TextInput accessibilityLabel="Dive site difficulty" value={form.difficulty} onChangeText={(value) => setField('difficulty', value)} style={styles.input} placeholder="Beginner, Intermediate..." /><Text style={styles.label}>Currents and conditions</Text><TextInput accessibilityLabel="Current information" multiline value={form.currentInfo} onChangeText={(value) => setField('currentInfo', value)} style={[styles.input, styles.multilineSmall]} placeholder="Typical current, tide or visibility" /><Text style={styles.label}>Highlights (comma separated)</Text><TextInput accessibilityLabel="Dive site highlights" value={form.highlights} onChangeText={(value) => setField('highlights', value)} style={styles.input} placeholder="Wall, swim-through, coral garden" /><Text style={styles.label}>Typical sightings (comma separated)</Text><TextInput accessibilityLabel="Typical sightings" value={form.typicalSightings} onChangeText={(value) => setField('typicalSightings', value)} style={styles.input} placeholder="Turtles, barracuda, frogfish" /><Text style={styles.formSection}>First route</Text><TextInput accessibilityLabel="Route name" value={form.routeName} onChangeText={(value) => setField('routeName', value)} style={styles.input} placeholder="Outer reef loop" /><TextInput accessibilityLabel="Route notes" value={form.routeNotes} onChangeText={(value) => setField('routeNotes', value)} style={styles.input} placeholder="Route notes" /><TextInput accessibilityLabel="Route points" value={form.routePoints} onChangeText={(value) => setField('routePoints', value)} style={styles.input} placeholder="latitude, longitude; latitude, longitude" /><Text style={styles.routeHint}>Use semicolon-separated coordinates to record a route, for example: 9.60, 123.78; 9.61, 123.79.</Text>{error ? <Text accessibilityRole="alert" style={styles.error}>{error}</Text> : null}<TouchableOpacity accessibilityRole="button" disabled={saving} onPress={saveSite} style={styles.saveButton}><Text style={styles.saveButtonText}>{saving ? 'Savingâ€¦' : editing ? 'Save changes' : 'Create dive site'}</Text></TouchableOpacity></ScrollView></View></View></Modal>
    <Modal visible={modal && speciesPickerOpen} transparent animationType="fade" onRequestClose={() => setSpeciesPickerOpen(false)}><View style={styles.backdrop}><View style={styles.speciesModal}><View style={styles.modalHeader}><View><Text style={styles.modalTitle}>Typical sightings</Text><Text style={styles.modalHint}>Choose species from the Pokedex catalog.</Text></View><TouchableOpacity accessibilityLabel="Close Pokedex species picker" onPress={() => setSpeciesPickerOpen(false)}><Text style={styles.close}>Ã—</Text></TouchableOpacity></View><TextInput accessibilityLabel="Search Pokedex species" value={sightingQuery} onChangeText={setSightingQuery} style={styles.input} placeholder="Search species or category" /><ScrollView nestedScrollEnabled style={styles.speciesPicker}>{filteredSightings.map((species) => { const selected = selectedTypicalSightings.includes(species.key); return <TouchableOpacity key={species.key} accessibilityRole="checkbox" accessibilityState={{ checked: selected }} onPress={() => setSelectedTypicalSightings((current) => selected ? current.filter((key) => key !== species.key) : [...current, species.key])} style={[styles.speciesOption, selected && styles.speciesOptionSelected]}><View style={[styles.speciesCheck, selected && styles.speciesCheckSelected]}><Text style={styles.speciesCheckText}>{selected ? 'âœ“' : ''}</Text></View><View style={styles.speciesOptionCopy}><Text style={styles.speciesOptionName}>{species.name}</Text><Text style={styles.speciesOptionCategory}>{species.category}</Text></View></TouchableOpacity>; })}{!filteredSightings.length ? <Text style={styles.noSpeciesSelected}>No Pokedex species found.</Text> : null}</ScrollView><View style={styles.selectedSpeciesRow}>{selectedTypicalSightings.map((key) => { const species = speciesForKey(key); return <TouchableOpacity key={key} accessibilityRole="button" accessibilityLabel={`Remove ${species?.name || key}`} onPress={() => setSelectedTypicalSightings((current) => current.filter((candidate) => candidate !== key))} style={styles.selectedSpecies}><Text style={styles.selectedSpeciesText}>{species?.name || key}</Text><Text style={styles.selectedSpeciesRemove}>Ã—</Text></TouchableOpacity>; })}</View><TouchableOpacity accessibilityRole="button" onPress={() => setSpeciesPickerOpen(false)} style={styles.saveButton}><Text style={styles.saveButtonText}>Done Â· {selectedTypicalSightings.length} selected</Text></TouchableOpacity></View></View></Modal>
    <Modal visible={narrowLayout && modal && !speciesPickerOpen} transparent animationType="none" onRequestClose={() => undefined}><View pointerEvents="none" style={styles.editorEdgePanel}><Text style={styles.editorEdgePanelText}>Details</Text></View></Modal>
  </ScrollView>;
}

function PanglaoMap({ map, sites, selectedId, placing, onSelect, onMapPress }: { map: OperationMapTemplate; sites: DiveSite[]; selectedId?: number; placing: boolean; onSelect: (site: DiveSite) => void; onMapPress: (event: any, metrics: { viewBoxX: number; viewBoxY: number; viewBoxWidth: number; viewBoxHeight: number; renderedWidth: number; renderedHeight: number }) => void }) {
  const [zoom, setZoom] = useState(1);
  const [renderedSize, setRenderedSize] = useState({ width: MAP_WIDTH, height: 330 });
  const viewBoxWidth = MAP_WIDTH / zoom;
  const viewBoxHeight = MAP_HEIGHT / zoom;
  const viewBoxX = (MAP_WIDTH - viewBoxWidth) / 2;
  const viewBoxY = (MAP_HEIGHT - viewBoxHeight) / 2;
  const metrics = { viewBoxX, viewBoxY, viewBoxWidth, viewBoxHeight, renderedWidth: renderedSize.width, renderedHeight: renderedSize.height };
  const selectedSite = sites.find((site) => site.id === selectedId);
  const selectedRoute = selectedSite?.routes?.[0]?.points || [];
  const routePath = selectedRoute.map((point, index) => { const projected = project(point.latitude, point.longitude, map); return `${index === 0 ? 'M' : 'L'}${projected.x.toFixed(2)},${projected.y.toFixed(2)}`; }).join(' ');
  return <View style={styles.mapCanvas}><Svg width="100%" height={330} viewBox={`${viewBoxX} ${viewBoxY} ${viewBoxWidth} ${viewBoxHeight}`} onLayout={(event: any) => { const width = Number(event?.nativeEvent?.layout?.width); const height = Number(event?.nativeEvent?.layout?.height); if (width && height) setRenderedSize({ width, height }); }} onPress={(event: any) => onMapPress(event, metrics)} accessibilityLabel="Panglao and Bohol operation map">
    <Path d="M0 0H900V470H0Z" fill="#dff4f4" />
    {BOHOL_FEATURES.map((feature) => <Path key={feature.name} d={geometryToPath(feature.geometry, map)} fill="#b8debf" stroke="#75ad91" strokeWidth="1.7" strokeLinejoin="round" />)}
    {BOHOL_FEATURES.filter((feature) => ['Panglao', 'Dauis', 'City of Tagbilaran', 'Baclayon'].includes(feature.name)).map((feature) => { const center = geometryCenter(feature.geometry, map); const label = feature.name === 'City of Tagbilaran' ? 'Tagbilaran' : feature.name; return <SvgText key={`label-${feature.name}`} x={center.x} y={center.y} fill="#2f6e65" fontSize="13" fontWeight="bold" textAnchor="middle">{label}</SvgText>; })}
    {routePath ? <Path d={routePath} fill="none" stroke="#f08a4b" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="10 8" /> : null}
    <SvgText x="610" y="438" fill="#34747a" fontSize="16" fontWeight="bold" textAnchor="middle">Bohol Sea</SvgText>
    {sites.map((site) => { const point = project(site.latitude, site.longitude, map); const active = selectedId === site.id; return <G key={site.id} onPress={() => onSelect(site)}>
      <Circle cx={point.x} cy={point.y} r={active ? 18 : 14} fill={active ? '#123b52' : '#0b777b'} opacity="0.2" />
      <Circle cx={point.x} cy={point.y} r={active ? 9 : 7} fill={active ? '#123b52' : '#0b777b'} stroke="#fff" strokeWidth="3" />
      <SvgText x={point.x + 13} y={point.y + 4} fill="#123b52" fontSize="13" fontWeight="bold">{site.name}</SvgText>
    </G>; })}
    {placing ? <SvgText x="30" y="42" fill="#123b52" fontSize="16" fontWeight="bold">CLICK TO PLACE DIVE SITE PIN</SvgText> : null}
  </Svg><View style={styles.zoomControls}><TouchableOpacity accessibilityLabel="Zoom in" accessibilityRole="button" onPress={() => setZoom((current) => Math.min(4, Number((current + 0.75).toFixed(2))))} style={styles.zoomButton}><Text style={styles.zoomButtonText}>+</Text></TouchableOpacity><TouchableOpacity accessibilityLabel="Zoom out" accessibilityRole="button" onPress={() => setZoom((current) => Math.max(1, Number((current - 0.75).toFixed(2))))} style={styles.zoomButton}><Text style={styles.zoomButtonText}>âˆ’</Text></TouchableOpacity><TouchableOpacity accessibilityLabel="Reset map zoom" accessibilityRole="button" onPress={() => setZoom(1)} style={styles.resetZoomButton}><Text style={styles.resetZoomText}>Reset</Text></TouchableOpacity></View></View>;
}

const styles = StyleSheet.create({
