import React, { useCallback, useState } from 'react';
import { ActivityIndicator, ScrollView, StyleSheet, Text, TouchableOpacity, View, useWindowDimensions } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';
import API from '../api/api';
import { DiveSite, PokedexSpecies } from '../types';

export default function CenterDiveSiteDetailScreen({ navigation, route }: any) {
  const siteId = route?.params?.siteId;
  const narrowLayout = useWindowDimensions().width < 640;
  const [site, setSite] = useState<DiveSite | null>(null);
  const [speciesCatalog, setSpeciesCatalog] = useState<PokedexSpecies[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const load = useCallback(async () => {
    setLoading(true); setError('');
    try { const [response, speciesResponse] = await Promise.all([API.get<DiveSite>(`/center/dive-sites/${siteId}`), API.get<PokedexSpecies[]>('/pokedex/species')]); setSite(response.data); setSpeciesCatalog(Array.isArray(speciesResponse.data) ? speciesResponse.data : []); }
    catch (requestError: any) { setError(requestError?.response?.data?.message || 'Could not load this dive site.'); }
    finally { setLoading(false); }
  }, [siteId]);
  useFocusEffect(useCallback(() => { load(); }, [load]));
  if (loading) return <View style={styles.center}><ActivityIndicator color="#123b52" /></View>;
  if (!site) return <View style={styles.center}><Text accessibilityRole="alert" style={styles.error}>{error || 'Dive site not found.'}</Text><TouchableOpacity onPress={load} style={styles.secondary}><Text style={styles.secondaryText}>Retry</Text></TouchableOpacity></View>;
  return <ScrollView style={styles.screen} contentContainerStyle={styles.content}>
    <View style={styles.hero}><Text style={styles.eyebrow}>DIVE ZONE PROFILE</Text><Text style={styles.title}>{site.name}</Text><Text style={styles.coordinates}>{site.latitude.toFixed(5)}, {site.longitude.toFixed(5)} Â· {site.difficulty || 'Difficulty not set'}</Text><Text style={styles.description}>{site.description || 'No description has been added yet.'}</Text></View>
    <View pointerEvents="none" style={profileStyles.floatingBadge}><Text style={profileStyles.floatingBadgeText}>LIVE SITE DATA</Text><Text style={profileStyles.floatingBadgeMeta}>updated moments ago</Text></View>
    {narrowLayout ? <View pointerEvents="none" style={profileStyles.compactRibbon}><Text style={profileStyles.compactRibbonText}>SITE PROFILE Â· {site.name}</Text></View> : null}
    <View style={styles.metrics}><View style={styles.metric}><Text style={styles.metricValue}>{site.minDepth ?? '?'}â€“{site.maxDepth ?? '?'} m</Text><Text style={styles.metricLabel}>depth range</Text></View><View style={styles.metric}><Text style={styles.metricValue}>{site.routes?.length || 0}</Text><Text style={styles.metricLabel}>routes</Text></View><View style={styles.metric}><Text style={styles.metricValue}>{site.typicalSightings?.length || 0}</Text><Text style={styles.metricLabel}>typical sightings</Text></View></View>
    <View style={styles.panel}><Text style={styles.panelTitle}>Highlights</Text>{site.highlights?.length ? <View style={styles.tagRow}>{site.highlights.map((highlight) => <Text key={highlight} style={styles.tag}>{highlight}</Text>)}</View> : <Text style={styles.muted}>Add the signature features of this site.</Text>}</View>
    <View style={styles.panel}><Text style={styles.panelTitle}>Typical sightings</Text>{site.typicalSightings?.length ? <View style={styles.tagRow}>{site.typicalSightings.map((sighting) => { const species = speciesCatalog.find((candidate) => candidate.key === sighting); return <Text key={sighting} style={styles.sighting}>{species?.name || sighting}</Text>; })}</View> : <Text style={styles.muted}>No sightings have been linked yet.</Text>}</View>
    <View pointerEvents="none" style={profileStyles.statusBar}><Text style={profileStyles.statusBarText}>CURRENT CONDITIONS</Text></View>
    <View style={styles.panel}><Text style={styles.panelTitle}>Currents and conditions</Text><Text style={styles.body}>{site.currentInfo || 'No current notes have been added yet.'}</Text></View>
    <View style={styles.panel}><Text style={styles.panelTitle}>Routes</Text>{site.routes?.length ? site.routes.map((routeItem) => <View key={routeItem.name} style={styles.route}><Text style={styles.routeName}>{routeItem.name}</Text><Text style={styles.routeMeta}>{routeItem.points?.length || 0} waypoints{routeItem.notes ? ` Â· ${routeItem.notes}` : ''}</Text></View>) : <Text style={styles.muted}>No route has been drawn yet.</Text>}</View>
    <TouchableOpacity accessibilityRole="button" onPress={() => navigation.goBack()} style={styles.secondary}><Text style={styles.secondaryText}>Back to dive sites map</Text></TouchableOpacity>
  </ScrollView>;
}

