    </> : <View style={styles.empty}><Text style={styles.emptyTitle}>Choose your operation map</Text><Text style={styles.muted}>Select Panglao to start placing dive zones.</Text></View>}
    <Modal visible={modal} transparent animationType="slide" onRequestClose={() => setModal(false)}><View style={styles.backdrop}><View style={styles.modal}><ScrollView keyboardShouldPersistTaps="handled"><View style={styles.modalHeader}><View><Text style={styles.modalTitle}>{editing ? 'Edit dive site' : 'Add dive site'}</Text><Text style={styles.modalHint}>The pin stays inside the selected operation map.</Text></View><TouchableOpacity accessibilityLabel="Close dive site form" onPress={() => setModal(false)}><Text style={styles.close}>×</Text></TouchableOpacity></View><Text style={styles.label}>Name *</Text><TextInput accessibilityLabel="Dive site name" value={form.name} onChangeText={(value) => setField('name', value)} placeholder="Balicasag Cathedral" style={styles.input} /><Text style={styles.label}>Description</Text><TextInput accessibilityLabel="Dive site description" multiline value={form.description} onChangeText={(value) => setField('description', value)} style={[styles.input, styles.multiline]} placeholder="What makes this zone special?" /><View style={styles.row}><View style={styles.half}><Text style={styles.label}>Latitude</Text><TextInput accessibilityLabel="Dive site latitude" keyboardType="decimal-pad" value={form.latitude} onChangeText={(value) => setField('latitude', value)} style={styles.input} /></View><View style={styles.half}><Text style={styles.label}>Longitude</Text><TextInput accessibilityLabel="Dive site longitude" keyboardType="decimal-pad" value={form.longitude} onChangeText={(value) => setField('longitude', value)} style={styles.input} /></View></View><View style={styles.row}><View style={styles.half}><Text style={styles.label}>Min depth (m)</Text><TextInput accessibilityLabel="Minimum depth" keyboardType="number-pad" value={form.minDepth} onChangeText={(value) => setField('minDepth', value)} style={styles.input} /></View><View style={styles.half}><Text style={styles.label}>Max depth (m)</Text><TextInput accessibilityLabel="Maximum depth" 