      <View style={styles.mapPanel}><View style={styles.mapPanelHeader}><View><Text style={styles.sectionTitle}>{map.name}</Text><Text style={styles.sectionHint}>{placing ? 'Click anywhere inside the map to set a new pin.' : 'Select a pin or card. Zoom and drag to explore; arrow keys also pan.'}</Text></View><Text style={styles.attribution}>{map.attribution}</Text></View><View style={styles.mapFrame}><PanglaoMap key={map.key} map={map} sites={visibleSites} selectedId={selected?.id} placing={placing} onSelect={(site) => { setSelected(site); setPlacing(false); }} onMapPress={handleMapPress} /></View></View>
      <View style={styles.resultsHeader}><Text style={styles.sectionTitle}>Dive zones</Text><Text style={styles.sectionHint}>{visibleSites.length} shown</Text></View>
      <View style={styles.siteGrid}>{visibleSites.map((site) => <TouchableOpacity key={site.id} accessibilityRole="button" accessibilityState={{ selected: selected?.id === site.id }} style={[styles.siteCard, selected?.id === site.id && styles.siteCardActive]} onPress={() => setSelected(site)}><View style={styles.siteCardTop}><Text style={styles.siteName}>{site.name}</Text><Text style={styles.difficulty}>{site.difficulty || 'Unrated'}</Text></View><Text numberOfLines={2} style={styles.siteDescription}>{site.description || 'No description yet.'}</Text><Text style={styles.siteMeta}>{site.minDepth ?? '?'}–{site.maxDepth ?? '?'} m · {(site.typicalSightings || []).length} typical sightings · {(site.routes || []).length} route{(site.routes || []).length === 1 ? '' : 's'}</Text></TouchableOpacity>)}</View>
      {!visibleSites.length ? <View style={styles.empty}><Text style={styles.emptyTitle}>No dive zones match</Text><Text style={styles.muted}>Try another search or place your first pin.</Text></View> : null}
      {selected ? <View style={styles.detailPanel}><View style={styles.detailCopy}><Text style={styles.eyebrow}>SELECTED DIVE ZONE</Text><Text style={styles.detailTitle}>{selected.name}</Text><Text style={styles.detailDescription}>{selected.description || 'Add a description so visiting divers know what to expect.'}</Text><Text style={styles.detailMeta}>{selected.latitude.toFixed(5)}, {selected.longitude.toFixed(5)} · {selected.difficulty || 'Difficulty not set'}</Text></View><View style={styles.detailActions}><TouchableOpacity accessibilityRole="button" onPress={() => navigation.navigate('CenterDiveSiteDetail', { siteId: selected.id })} style={styles.detailButton}><Text style={styles.detailButtonText}>Open site profile</Text></TouchableOpacity><TouchableOpacity accessibilityRole="button" onPress={() => openEdit(selected)} style={styles.editButton}><Text style={styles.editButtonText}>Edit</Text></TouchableOpacity><TouchableOpacity accessibilityRole="button" disabled={saving} onPress={() => removeSite(selected)} style={styles.deleteButton}><Text style={styles.deleteButtonText}>Remove</Text></TouchableOpacity></View></View> : null}
    </> : <View style={styles.empty}><Text style={styles.emptyTitle}>Choose your operation map</Text><Text style={styles.muted}>Select Panglao to start placing dive zones.</Text></View>}
    <Modal visible={modal} transparent animationType="slide" onRequestClose={() => { if (!saving) setModal(false); }}><View style={styles.backdrop}><View style={styles.modal}><ScrollView keyboardShouldPersistTaps="handled"><View style={styles.modalHeader}><View><Text style={styles.modalTitle}>{editing ? 'Edit dive site' : 'Add dive site'}</Text><Text style={styles.modalHint}>The pin stays inside the selected operation map.</Text></View><TouchableOpacity accessibilityRole="button" accessibilityLabel="Close dive site form" disabled={saving} onPress={() => setModal(false)}><Text style={styles.close}>×</Text></TouchableOpacity></View><Text style={styles.label}>Name *</Text><TextInput accessibilityLabel="Dive site name" value={form.name} onChangeText={(value) => setField('name', value)} placeholder="Balicasag Cathedral" style={styles.input} /><Text style={styles.label}>Description</Text><TextInput accessibilityLabel="Dive site description" multiline value={form.description} onChangeText={(value) => setField('description', value)} style={[styles.input, styles.multiline]} placeholder="What makes this zone special?" /><View style={styles.row}><View style={styles.half}><Text style={styles.label}>Latitude</Text><TextInput accessibilityLabel="Dive site latitude" keyboardType="decimal-pad" value={form.latitude} onChangeText={(value) => setField('latitude', value)} style={styles.input} /></View><View style={styles.half}><Text style={styles.label}>Longitude</Text><TextInput accessibilityLabel="Dive site longitude" keyboardType="decimal-pad" value={form.longitude} onChangeText={(value) => setField('longitude', value)} style={styles.input} /></View></View><View style={styles.row}><View style={styles.half}><Text style={styles.label}>Min depth (m)</Text><TextInput accessibilityLabel="Minimum depth" keyboardType="number-pad" value={form.minDepth} onChangeText={(value) => setField('minDepth', value)} style={styles.input} /></View><View style={styles.half}><Text style={styles.label}>Max depth (m)</Text><TextInput accessibilityLabel="Maximum depth" keyboardType="number-pad" value={form.maxDepth} onChangeText={(value) => setField('maxDepth', value)} style={styles.input} /></View></View><Text style={styles.label}>Difficulty</Text><TextInput accessibilityLabel="Dive site difficulty" value={form.difficulty} onChangeText={(value) => setField('difficulty', value)} style={styles.input} placeholder="Beginner, Intermediate..." /><Text style={styles.label}>Currents and conditions</Text><TextInput accessibilityLabel="Current information" multiline value={form.currentInfo} onChangeText={(value) => setField('currentInfo', value)} style={[styles.input, styles.multilineSmall]} placeholder="Typical current, tide or visibility" /><Text style={styles.label}>Highlights (comma separated)</Text><TextInput accessibilityLabel="Dive site highlights" value={form.highlights} onChangeText={(value) => setField('highlights', value)} style={styles.input} placeholder="Wall, swim-through, coral garden" /><Text style={styles.label}>Typical sightings</Text><TouchableOpacity accessibilityRole="button" accessibilityLabel="Choose typical sightings" onPress={() => setSpeciesPickerOpen(true)} style={styles.input}><Text style={styles.editButtonText}>Choose marine life · {selectedTypicalSightings.length} selected</Text></TouchableOpacity><View style={styles.selectedSpeciesRow}>{selectedTypicalSightings.map((key) => <TouchableOpacity key={key} accessibilityRole="button" accessibilityLabel={`Remove ${speciesForKey(key)?.name || key}`} onPress={() => setSelectedTypicalSightings((current) => current.filter((item) => item !== key))} style={styles.selectedSpecies}><Text style={styles.selectedSpeciesText}>{speciesForKey(key)?.name || key} ×</Text></TouchableOpacity>)}</View><Text style={styles.formSection}>First route</Text><TextInput accessibilityLabel="Route name" value={form.routeName} onChangeText={(value) => setField('routeName', value)} style={styles.input} placeholder="Outer reef loop" /><TextInput accessibilityLabel="Route notes" value={form.routeNotes} onChangeText={(value) => setField('routeNotes', value)} style={styles.input} placeholder="Route notes" /><TextInput accessibilityLabel="Route points" value={form.routePoints} onChangeText={(value) => setField('routePoints', value)} style={styles.input} placeholder="latitude, longitude; latitude, longitude" /><Text style={styles.routeHint}>Use semicolon-separated coordinates to record a route, for example: 9.60, 123.78; 9.61, 123.79.</Text>{error ? <Text accessibilityRole="alert" style={styles.error}>{error}</Text> : null}<TouchableOpacity accessibilityRole="button" disabled={saving} onPress={saveSite} style={styles.saveButton}><Text style={styles.saveButtonText}>{saving ? 'Saving…' : editing ? 'Save changes' : 'Create dive site'}</Text></TouchableOpacity></ScrollView></View></View></Modal>
    <Modal visible={modal && speciesPickerOpen} transparent animationType="fade" onRequestClose={() => setSpeciesPickerOpen(false)}><View style={styles.backdrop}><View style={styles.speciesModal}><View style={styles.modalHeader}><View><Text style={styles.modalTitle}>Typical sightings</Text><Text style={styles.modalHint}>Choose species from the Pokedex catalog.</Text></View><TouchableOpacity accessibilityRole="button" accessibilityLabel="Close Pokedex species picker" onPress={() => setSpeciesPickerOpen(false)}><Text style={styles.close}>×</Text></TouchableOpacity></View><TextInput accessibilityLabel="Search Pokedex species" value={sightingQuery} onChangeText={setSightingQuery} style={styles.input} placeholder="Search species or category" /><ScrollView nestedScrollEnabled style={styles.speciesPicker}>{filteredSightings.map((species) => { const selected = selectedTypicalSightings.includes(species.key); return <TouchableOpacity key={species.key} accessibilityRole="checkbox" accessibilityState={{ checked: selected }} onPress={() => setSelectedTypicalSightings((current) => selected ? current.filter((key) => key !== species.key) : [...current, species.key])} style={[styles.speciesOption, selected && styles.speciesOptionSelected]}><View style={[styles.speciesCheck, selected && styles.speciesCheckSelected]}><Text style={styles.speciesCheckText}>{selected ? '✓' : ''}</Text></View><View style={styles.speciesOptionCopy}><Text style={styles.speciesOptionName}>{species.name}</Text><Text style={styles.speciesOptionCategory}>{species.category}</Text></View></TouchableOpacity>; })}{!filteredSightings.length ? <Text style={styles.noSpeciesSelected}>No Pokedex species found.</Text> : null}</ScrollView><View style={styles.selectedSpeciesRow}>{selectedTypicalSightings.map((key) => { const species = speciesForKey(key); return <TouchableOpacity key={key} accessibilityRole="button" accessibilityLabel={`Remove ${species?.name || key}`} onPress={() => setSelectedTypicalSightings((current) =>