    <Modal visible={modal && speciesPickerOpen} transparent animationType="fade" onRequestClose={() => setSpeciesPickerOpen(false)}><View style={styles.backdrop}><View style={styles.speciesModal}><View style={styles.modalHeader}><View><Text style={styles.modalTitle}>Typical sightings</Text><Text style={styles.modalHint}>Choose species from the Pokedex catalog.</Text></View><TouchableOpacity accessibilityRole="button" accessibilityLabel="Close Pokedex species picker" onPress={() => setSpeciesPickerOpen(false)}><Text style={styles.close}>×</Text></TouchableOpacity></View><TextInput accessibilityLabel="Search Pokedex species" value={sightingQuery} onChangeText={setSightingQuery} style={styles.input} placeholder="Search species or category" /><ScrollView nestedScrollEnabled style={styles.speciesPicker}>{filteredSightings.map((species) => { const selected = selectedTypicalSightings.includes(species.key); return <TouchableOpacity key={species.key} accessibilityRole="checkbox" accessibilityState={{ checked: selected }} onPress={() => setSelectedTypicalSightings((current) => selected ? current.filter((key) => key !== species.key) : [...current, species.key])} style={[styles.speciesOption, selected && styles.speciesOptionSelected]}><View style={[styles.speciesCheck, selected && styles.speciesCheckSelected]}><Text style={styles.speciesCheckText}>{selected ? '✓' : ''}</Text></View><View style={styles.speciesOptionCopy}><Text style={styles.speciesOptionName}>{species.name}</Text><Text style={styles.speciesOptionCategory}>{species.category}</Text></View></TouchableOpacity>; })}{!filteredSightings.length ? <Text style={styles.noSpeciesSelected}>No Pokedex species found.</Text> : null}</ScrollView><View style={styles.selectedSpeciesRow}>{selectedTypicalSightings.map((key) => { const species = speciesForKey(key); return <TouchableOpacity key={key} accessibilityRole="button" accessibilityLabel={`Remove ${species?.name || key}`} onPress={() => setSelectedTypicalSightings((current) =>