    if ([form.minDepth, form.maxDepth].some((value) => value.trim() && (!Number.isFinite(Number(value)) || Number(value) < 0)) || (form.minDepth.trim() && form.maxDepth.trim() && Number(form.minDepth) > Number(form.maxDepth))) {
